# Day length follows the sun smoothly through the year (about 45° latitude: ~16 h at midsummer, ~8 h at midwinter).
patch('Core/SimClock.cs', [
("""        /// <summary>Sunrise and sunset by season: long summer days, short winter ones.</summary>
        public int Sunrise => Season switch { Season.Spring => 6, Season.Summer => 5, Season.Autumn => 7, _ => 8 };
        public int Sunset => Season switch { Season.Spring => 19, Season.Summer => 21, Season.Autumn => 18, _ => 16 };""",
"""        /// <summary>
        /// Hours of daylight today: following the sun smoothly through the year, about 16 at
        /// midsummer and 8 at midwinter (a mid-latitude valley, ~45°).
        /// </summary>
        public double DayLength => 12 + 4 * Math.Cos(2 * Math.PI * (DayOfYear - (DaysPerSeason + DaysPerSeason / 2)) / DaysPerYear);
        public int Sunrise => (int)Math.Round(12.5 - DayLength / 2);
        public int Sunset => (int)Math.Round(12.5 + DayLength / 2);"""),
])
s = open('Core/SimClock.cs', encoding='utf-8').read()
if 'using System;' not in s:
    s = 'using System;\n' + s
open('Core/SimClock.cs', 'w', encoding='utf-8').write(s)

