    double fromStomach = Math.Min(p.Stomach, burn);
    p.Stomach -= fromStomach;
    p.Reserve = Math.Max(0, p.Reserve - (burn - fromStomach));
    // A well-filled stomach slowly lays down reserves, up to what this body can carry.
