        internal bool SamePeople(Person o)
        {
            if (Tribe == null) return false;
            var theirs = Region.BandOf(o);
            return theirs != null && theirs.Tribe == Tribe;
            loser.Injury = Inheritance.Clamp01(loser.Injury + loserWound);
            winner.Injury = Inheritance.Clamp01(winner.Injury + winnerWound);
            ThisYear.Fights++;
            double attackerWound = attacker == loser ? loserWound : winnerWound;
            double targetWound = target == loser ? loserWound : winnerWound;

            var deed = new Deed { Day = Clock.Day, Actor = attacker, Act = Act.Attack, Target = target, Amount = targetWound, Answers = answers,
                                  Context = Lesson(Act.Attack, RelationTo(attacker, target)) };
            var seen = Happen(deed);
            // A fight between partners is an occasion to think about leaving.
            if (attacker.Partner == target) { ConsiderLeaving(target, null); ConsiderLeaving(attacker, null); }
            // A beating for a wrong: the wrongdoer learns what the wrong cost.
            if (answers != null) Credit(answers, -targetWound * WoundCost, seen, attacker);
            // The attacker learns what hitting got them: the pain they took, and the anger they spent.
            Learn(attacker, deed.Context, -attackerWound * WoundCost, CulturalDefault(Act.Attack, RelationTo(attacker, target), null));
            attacker.AddGrievance(target, -attacker.GetGrievance(target) * (attacker == winner ? 0.7 : 0.3));
        /// the people they'd be with, and how well each band is doing.
        /// </summary>
        internal void ConsiderJoining(Simulation other)
        {
            foreach (var p in Band.Members.Where(p => p.Alive && Grown(p)).ToList())
            {
                if (!Band.Members.Contains(p) || Clock.Day - p.LeftDay < SimClock.DaysPerYear || other.Extinct) continue;
                var family = Band.Members.Where(o => o == p || o == p.Partner || (p.Children.Contains(o) && o.AgeYears(Clock) < 14)).ToList();
                double here = Ties(p, Band.Members.Except(family));
                // A group too small to hunt together and carry each other through bad times is a hard
                // place to be when times are bad (in good times a small camp does fine).
                int adultsHere = Band.Members.Count(Grown), adultsThere = other.Band.Members.Count(Grown);
            for (int i = 0; i < P.Drives.Length; i++)
            {
                double mid = (P.Drives[i] + _with.Drives[i]) / 2;
                P.Drives[i] += (mid - P.Drives[i]) * 0.002 * (0.5 + P.M(MindTrait.Openness));
            }
            // When fondness has become mutual, two unpaired people pair up.
            var withBand = sim.Region.BandOf(_with) ?? sim;
            using (Core.Profiler.Measure("talk pairing")) if (sim.WouldPair(P, _with, sim, withBand)) sim.Pair(P, _with);
            else using (Core.Profiler.Measure("talk leaving")) if (P.Partner != null && _with.Partner == null) sim.ConsiderLeaving(P, _with);
            if (P.Restless) using (Core.Profiler.Measure("consider moving")) sim.ConsiderMoving(P);
        }
    }

