        region.Tribes.Remove(region.Tribes[region.Tribes.Count - 1]);
        camp.Band.Name = camp.CampName(camp.Band.Members.Where(camp.Grown).OrderByDescending(m => m.AgeYears(region.Clock)).FirstOrDefault());
        // One people, one culture: the same customs, and the same expectations of how people
