                int adultsHere = Band.Members.Count(Grown), adultsThere = other.Band.Members.Count(Grown);
                double shortHere = Math.Max(0, Needed(p) - adultsHere) / Needed(p), shortThere = Math.Max(0, Needed(p) - adultsThere - 1) / Needed(p);
