    open(p, 'w', encoding='utf-8').write(s)

# --- Customs: taking sides, duels -------------------------------------------------------------
patch('Customs.cs', [
("""    /// <item>hunting: how much standing a hunter wins by hunting (0 none, 1 hunting is what makes a name).</item>""",
"""    /// <item>hunting: how much standing a hunter wins by hunting (0 none, 1 hunting is what makes a name).</item>
    /// <item>sides: whether people take sides in others' quarrels (0 it's their business, 1 kin and friends
    /// pile in): what turns quarrels into brawls and feuds between families.</item>
    /// <item>duel: whether a grudge is settled one on one, others watching and keeping out (0 never, 1 the
    /// accepted way); how far a duel goes is the people's sense of how far violence goes.</item>"""),
("""        internal const string RationTopic = "norm:rationing", DemandTopic = "norm:demand", EldersTopic = "norm:elders", HuntingTopic = "norm:hunting";""",
"""        internal const string RationTopic = "norm:rationing", DemandTopic = "norm:demand", EldersTopic = "norm:elders", HuntingTopic = "norm:hunting";
        internal const string SidesTopic = "norm:sides", DuelTopic = "norm:duel";
        internal static double Sides(Person p) => p.Expect.Get(SidesTopic, 0.4);
        internal static double Duel(Person p) => p.Expect.Get(DuelTopic, 0.2);"""),
("""            double elders = Math.Max(0, Rng.Normal(1, 0.4)), hunting = Inheritance.Clamp01(Rng.Normal(0.4, 0.2));""",
"""            double elders = Math.Max(0, Rng.Normal(1, 0.4)), hunting = Inheritance.Clamp01(Rng.Normal(0.4, 0.2));
            double sides = Inheritance.Clamp01(Rng.Normal(0.4, 0.25)), duel = Inheritance.Clamp01(Rng.Normal(0.2, 0.25));"""),
("""                p.Expect.Absorb(HuntingTopic, Inheritance.Clamp01(hunting + Rng.Normal(0, 0.05)), 1, 0);""",
"""                p.Expect.Absorb(HuntingTopic, Inheritance.Clamp01(hunting + Rng.Normal(0, 0.05)), 1, 0);
                p.Expect.Absorb(SidesTopic, Inheritance.Clamp01(sides + Rng.Normal(0, 0.05)), 1, 0);
                p.Expect.Absorb(DuelTopic, Inheritance.Clamp01(duel + Rng.Normal(0, 0.05)), 1, 0);"""),
])

# --- Deeds done far from camp are seen only by those there ------------------------------------
patch('People/Deeds.cs', [
("""        /// <summary>Whether anyone besides the actor saw it.</summary>""",
"""        /// <summary>Done away from camp (an ambush): only the people there know of it.</summary>
        public bool Far;
        /// <summary>Whether anyone besides the actor saw it.</summary>"""),
])
patch('Society.cs', [
("""                bool involved = deed.Act != Act.Take && (m == deed.Target || (deed.Hearth != null && m.Home == deed.Hearth));
                if (involved || AwakeInCamp(m) && Rng.Chance""",
"""                bool involved = deed.Act != Act.Take && (m == deed.Target || (deed.Hearth != null && m.Home == deed.Hearth && !deed.Far));
                if (involved || !deed.Far && AwakeInCamp(m) && Rng.Chance"""),
# Unseen attacks are learned apart from seen ones: they cost less in the eyes of others.
("""                    p.Expect.Absorb(Lesson(Act.Attack, rel), Vary(rel == Relation.Outsider ? violenceOut : violence), 1, 0);""",
"""                    p.Expect.Absorb(Lesson(Act.Attack, rel), Vary(rel == Relation.Outsider ? violenceOut : violence), 1, 0);
                    p.Expect.Absorb(Lesson(Act.Attack, rel, false), Vary((rel == Relation.Outsider ? violenceOut : violence) + 1), 1, 0);"""),
# A quarrel between two: a duel where that's the custom, otherwise a fight others may join.
("""            bool overFood = answers?.Act == Act.Take;
            Fight(new[] { attacker }, new[] { target }, answers, overFood, inCamp: Band.Members.Contains(attacker) && Band.Members.Contains(target));""",
"""            bool overFood = answers?.Act == Act.Take;
            bool here = Band.Members.Contains(attacker) && Band.Members.Contains(target);
            // Where a people settles grudges one on one, the two fight it out and the rest watch.
            bool duel = here && Rng.Chance((Duel(attacker) + Duel(target)) / 2);
            Fight(new[] { attacker }, new[] { target }, answers, overFood, inCamp: here && !duel, kind: duel ? "duel" : "quarrel");"""),
])

# --- Fights: side-taking custom, duels, far deeds, ambush ---------------------------------------
patch('Fights.cs', [
("""        internal FightResult Fight(IList<Person> sideA, IList<Person> sideB, Deed? answers, bool overFood, bool inCamp, string kind = "quarrel")""",
 """        internal FightResult Fight(IList<Person> sideA, IList<Person> sideB, Deed? answers, bool overFood, bool inCamp, string kind = "quarrel", bool far = false)"""),
