internal static double Elders(Person p) => p.Expect.Get(EldersTopic, 1);
internal static double HuntingPrestige(Person p) => p.Expect.Get(HuntingTopic, 0.4);

/// <summary>
/// The rationing custom is judged by the seasons it had a say in: a family that had to budget its
/// food and still ran out and went hungry learns to pinch harder; one that pinched and watched the
/// food it held back rot learns it pinched for nothing (the more of it rotted, the clearer the
/// lesson). A season with no budgeting to do teaches nothing about budgeting.
/// </summary>
void LearnRationing(Person p)
{
    var h = p.Home;
    if (Off("rationlearn"))
    {
        // The old rule: any hard season teaches rationing; stores rotting in a good one unteaches it.
        if (p.WinterLow < 0.5) p.Expect.Absorb(RationTopic, 1, 0.1, Rationing(p));
        else if (h != null && p.WinterLow > 0.8 && h.StoresSpoiledRecent > h.Members.Count * 2) p.Expect.Absorb(RationTopic, 0, 0.05, Rationing(p));
        return;
    }
    if (h == null || !h.HadToBudget) { ThisYear.RationNone++; return; }
    if (h.RanOut && p.WinterLow < 0.5) { p.Expect.Absorb(RationTopic, 1, 0.1, Rationing(p)); ThisYear.RationUp++; }
    else if (h.HeldBack > 0 && h.StoresRotted > 0) { p.Expect.Absorb(RationTopic, 0, 0.1 * Math.Min(1, h.StoresRotted / h.HeldBack), Rationing(p)); ThisYear.RationDown++; }
    else ThisYear.RationHeld++;
}

/// <summary>A new season's budgeting starts fresh (after everyone has drawn the last one's lesson).</summary>
void NewBudgetSeason()
{
    foreach (var h in Band.Households) { h.HadToBudget = h.RanOut = false; h.HeldBack = h.StoresRotted = 0; }
}

void SeedCustoms(List<Person> group)

