patch('People/Household.cs',[("""        /// budget at all, the food they held back by it, the keeping food that rotted anyway, and whether
        /// they ran out regardless.
        /// </summary>
        public bool HadToBudget, RanOut;
        public double HeldBack, StoresRotted, StoresKept;""","""        /// budget at all, the keeping food they had when they started to, the food they held back by it,
        /// the keeping food that rotted anyway, and whether they ran out regardless.
        /// </summary>
        public bool HadToBudget, RanOut;
        public double BudgetStart, HeldBack, StoresRotted, StoresKept;""")])
patch('Activities/CampActivities.cs',[("""                home.HadToBudget = true;""","""                if (!home.HadToBudget) home.BudgetStart = Decider.Keeping(sim, home);
                home.HadToBudget = true;""")])
patch('Customs.cs',[
("""        /// <summary>
        /// The rationing custom is judged by the seasons it had a say in: a family that had to budget its
        /// food and still ran out and went hungry learns to pinch harder; one that pinched and watched its
        /// stores rot learns it pinched for nothing. Food held back rots like the rest of the store, so the
        /// lesson is as strong as the share of the store that went bad: with good pits and pots little is
        /// lost and budgeting pays; where stores rot fast it doesn't. A season with no budgeting to do teaches nothing about budgeting.
        /// </summary>""","""        /// <summary>
        /// The rationing custom is judged by the seasons it had a say in, by what a family could see it do:
        /// <list type="bullet">
        /// <item>They had stores to spread, budgeted, and still ran out and went hungry: pinch harder. As
        /// strong as what they had to spread (with next to nothing put by, pinching couldn't have saved
        /// them, and they don't blame it).</item>
        /// <item>They pinched and still have more than the lean time ahead calls for: they went hungry for
        /// nothing, as strong as the surplus is to what they held back. (Autumn food kept for winter is
        /// not a surplus.)</item>
        /// <item>They pinched and watched the store rot: food held back rots like the rest, so as strong as
        /// the share of the store that went bad.</item>
        /// <item>They budgeted and came through without running out or waste: it worked; nothing to change.</item>
        /// </list>
        /// So the custom settles where each world's food puts it: low where there's little to keep, higher
        /// with good storage and hard winters. A season with no budgeting to do teaches nothing about it.
        /// </summary>"""),
("""            if (h.RanOut && p.WinterLow < 0.5) { p.Expect.Absorb(RationTopic, 1, 0.1, Rationing(p)); ThisYear.RationUp++; }
            else if (h.HeldBack > 0 && h.StoresRotted > 0) { p.Expect.Absorb(RationTopic, 0, 0.1 * Math.Min(1, h.StoresRotted * Core.SimClock.DaysPerSeason / Math.Max(1, h.StoresKept)), Rationing(p)); ThisYear.RationDown++; }
            else ThisYear.RationHeld++;""",
"""            int mouths = Math.Max(1, h.Members.Count);
            if (h.RanOut && p.WinterLow < 0.5)
            {
                double hadToSpread = Math.Min(1, h.BudgetStart / (mouths * 0.9 * Core.SimClock.DaysPerSeason));
                if (hadToSpread > 0) { p.Expect.Absorb(RationTopic, 1, 0.1 * hadToSpread, Rationing(p)); ThisYear.RationUp++; }
                else ThisYear.RationHeld++;
                return;
            }
            if (h.HeldBack <= 0) { ThisYear.RationHeld++; return; }
            double surplus = Math.Max(0, Activities.Decider.Keeping(this, h) - mouths * 0.9 * Activities.Decider.LeanDays(this, p));
            double tooStrict = Math.Max(Math.Min(1, surplus / h.HeldBack), Math.Min(1, h.StoresRotted * Core.SimClock.DaysPerSeason / Math.Max(1, h.StoresKept)));
            if (tooStrict > 0) { p.Expect.Absorb(RationTopic, 0, 0.1 * tooStrict, Rationing(p)); ThisYear.RationDown++; }
            else ThisYear.RationHeld++;"""),
("h.HeldBack = h.StoresRotted = h.StoresKept = 0;","h.BudgetStart = h.HeldBack = h.StoresRotted = h.StoresKept = 0;"),
])
EOF
